    public List<Integer> neighbours(int vertex) {
        return Collections.unmodifiableList(adjacency.get(checkVertex(vertex)));
    }

    private int checkVertex(int vertex) {
        return Objects.checkIndex(vertex, adjacency.size());
    }
}

